
'use strict';
const KEY='aventura-tesoro-v1';const $=s=>document.querySelector(s);const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const topics=[['🏝️','Isla de las Tablas','Grupos iguales, grandes descubrimientos'],['🌳','Bosque del Ingenio','Piensa, descompón y resuelve'],['⛰️','Montaña de los Números','Multiplica y reparte el tesoro'],['⛵','Bahía de las Historias','Cada historia abre un mundo']];
const defaults=()=>({name:'',avatar:'🦜',coins:0,total:0,goal:1,missions:[],ledger:[],claims:[],days:[],weekly:[],reviewDays:[],readRatings:{},settings:{cap:50,mission:10,first:2,help:1,review:5,weekly:10},rewards:[['🎲','Elegir un juego familiar',100],['🍿','Tarde de películas',200],['🧺','Picnic en familia',300],['🎬','Visita al cine',500],['🛍️','Compras en familia',700],['🏖️','Visita a la playa',2000]].map((r,i)=>({id:i,icon:r[0],name:r[1],cost:r[2],enabled:false,condition:i===4?'Con presupuesto acordado por el adulto.':i===5?'Sujeto a planeación y disponibilidad familiar.':''}))});
let state;try{state=JSON.parse(localStorage.getItem(KEY))||defaults()}catch{state=defaults()}let view='map',selectedAvatar=state.avatar,mission=null,reading=null,adult=false;
function save(){try{localStorage.setItem(KEY,JSON.stringify(state))}catch{toast('No se pudo guardar: revisa el espacio y los permisos del navegador.')}}
function day(){return new Intl.DateTimeFormat('en-CA',{timeZone:'America/Mexico_City',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())}
function week(){const d=new Date(day()+'T12:00:00Z');d.setUTCDate(d.getUTCDate()-((d.getUTCDay()+6)%7));return d.toISOString().slice(0,10)}
function earnedToday(){return state.ledger.filter(x=>x.day===day()&&x.kind==='earn').reduce((a,x)=>a+x.amount,0)}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',4000)}
function award(n,label){const amount=Math.max(0,Math.min(n,state.settings.cap-earnedToday()));if(amount){state.coins+=amount;state.total+=amount;state.ledger.push({day:day(),amount,label,kind:'earn'})}return amount}
function page(p){stopNarration();view=p;mission=null;reading=null;document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.id==='nav-'+p));$('#balance').textContent=state.coins;if(p==='map')map();if(p==='rewards')rewards();if(p==='adult')adultPage();window.scrollTo(0,0)}
function map(){const goal=state.rewards.find(x=>x.id===state.goal)||state.rewards[0];const done=state.missions.length;$('#app').innerHTML=`<div class="row between"><div><div class="eyebrow">TU BITÁCORA DE EXPLORACIÓN</div><h1>¡Rumbo a una nueva aventura, ${esc(state.name||'capitana')}!</h1><div class="muted">Cuatro islas por descubrir. Un pequeño logro a la vez.</div></div><button class="outline" onclick="editProfile()">${state.avatar} Mi tripulación</button></div><div class="layout"><section class="map" aria-label="Mapa de las cuatro islas"><svg viewBox="0 0 850 510" preserveAspectRatio="none" aria-hidden="true"><defs><pattern id="waves" width="70" height="48" patternUnits="userSpaceOnUse"><path d="M10 24q8 7 16 0t16 0" fill="none" stroke="#aed2c6" stroke-width="2"/></pattern></defs><rect width="850" height="510" fill="url(#waves)"/><path d="M190 150C330 20 550 100 610 150S760 330 600 370S250 430 200 330S260 210 190 150" fill="none" stroke="#598b79" stroke-width="3" stroke-dasharray="7 12"/><path d="M70 160Q90 50 220 70T360 180Q310 250 160 235T70 160M470 120Q490 20 650 40T780 160Q720 220 560 200T470 120M120 375Q80 265 240 275T380 390Q310 480 190 455T120 375M500 365Q490 260 660 265T815 390Q750 470 600 450T500 365" fill="#a6cda4" stroke="#f3dfac" stroke-width="18"/><text x="405" y="260" font-size="45">⛵</text><text x="60" y="470" font-size="36">🐢</text><text x="750" y="60" font-size="32">☁️</text><text x="380" y="70" font-size="30">☁️</text></svg>${topics.map((t,i)=>`<button class="island i${i}" onclick="choose(${i})"><span>${t[0]}</span>${t[1]}<small>${state.missions.filter(m=>m.topic===i).length} misiones completadas · Explorar →</small></button>`).join('')}<div class="map-tag">EL ARCHIPIÉLAGO DE LOS PEQUEÑOS LOGROS</div><div class="compass" aria-hidden="true">✧</div></section><aside class="side"><div class="card next"><div class="eyebrow" style="color:#e7c978">LA SIGUIENTE PARADA</div><h2 style="margin:14px 0">${state.avatar} ¿Lista para zarpar?</h2><p>${recommendation()}</p><button class="gold" onclick="choose(${recommendedTopic()})">Comenzar misión →</button><p class="small" style="margin-bottom:0">Unos minutos bastan. Sin cronómetro.</p></div><div class="card"><div class="eyebrow">MI PRÓXIMO TESORO</div><h3 style="margin-top:15px">${goal.icon} ${esc(goal.name)}</h3><div class="progress"><i style="width:${Math.min(100,state.coins/goal.cost*100)}%"></i></div><div class="row between small"><b>${state.coins} / ${goal.cost} 🪙</b><span>${goal.enabled?'Disponible':'Por habilitar en familia'}</span></div><button class="outline" style="margin-top:18px;width:100%" onclick="page('rewards')">Ver mis tesoros</button></div></aside></div><div class="row between notice"><span>✦ ${done} misiones completadas · ${state.days.length} días de exploración</span><span>Hoy: ${earnedToday()} / ${state.settings.cap} monedas · Los errores también enseñan.</span></div>`}
function recommendedTopic(){if(!state.missions.length)return 0;const counts=topics.map((_,i)=>state.missions.filter(m=>m.topic===i).length);return counts.indexOf(Math.min(...counts))}
function recommendation(){if(!state.missions.length)return 'Empecemos con la tabla del 2: descubrirás que multiplicar es formar grupos iguales.';return 'Hoy podemos explorar '+topics[recommendedTopic()][1]+'. Alternar temas ayuda a seguir descubriendo.'}
function editProfile(){$('#nickname').value=state.name;selectedAvatar=state.avatar;renderAvatars();$('#profile').showModal()}
function renderAvatars(){$('#avatars').innerHTML=[['🦜','Loro'],['🐈','Gata pirata'],['🐢','Tortuga navegante'],['🐒','Monita exploradora'],['🐬','Delfín']].map(([a,n])=>`<button type="button" class="${selectedAvatar===a?'chosen':''}" aria-label="${n}" aria-pressed="${selectedAvatar===a}" onclick="selectedAvatar='${a}';renderAvatars()">${a}</button>`).join('')}
$('#profile-form').onsubmit=e=>{e.preventDefault();const n=$('#nickname').value.trim();if(!n)return;state.name=n;state.avatar=selectedAvatar;save();$('#profile').close();page('map');if(!sessionStarted)startAdventure()};
function choose(t){stopNarration();view='mission';if(t===0)return chooseTableIsland();if(t===3)return chooseReading();$('#app').innerHTML=`<section class="mission"><button class="soft" onclick="page('map')">← Volver al mapa</button><div class="card" style="margin-top:20px"><div class="eyebrow">ELIGE TU RUMBO</div><h1>${topics[t][0]} ${topics[t][1]}</h1><p>${topics[t][2]}. Puedes usar pistas y volver a intentar.</p>${t===0?'<label for="table">¿Qué tabla exploramos?</label><select id="table">'+[2,3,4,5,6,7,8,9,10,0].map(n=>`<option value="${n}">${n?'Tabla del '+n:'Tablas mezcladas'}</option>`).join('')+'</select><label for="level">¿Cómo empezamos?</label><select id="level"><option value="0">Con dibujos: grupos de hasta 5 monedas</option><option value="1">Un paso más: hasta 10 y números faltantes</option></select>':''}${t===1?'<label for="level">Tu nivel de hoy</label><select id="level"><option value="0">Primeros pasos: sin llevar ni pedir prestado</option><option value="1">Un paso más: con reagrupación</option></select>':''}${t===2?'<label for="operation">¿Qué practicamos?</label><select id="operation"><option value="mul">Multiplicar</option><option value="div">Repartir: divisiones exactas</option><option value="rem">Divisiones con residuo</option></select><label for="level">Dificultad</label><select id="level"><option value="0">Primeros pasos</option><option value="1">Un paso más</option></select>':''}<div class="row" style="margin-top:25px"><button class="gold" onclick="start(${t},false)">¡Comenzar!</button><button class="outline" onclick="start(${t},true)">Repasar errores pendientes</button></div><p class="small muted">El repaso usa ejercicios nuevos del tema y conserva la configuración elegida.</p></div></section>`}
function newId(){return typeof crypto!=='undefined'&&typeof crypto.randomUUID==='function'?crypto.randomUUID():Date.now().toString(36)+'-'+Math.random().toString(36).slice(2)}
const rnd=(a,b)=>Math.floor(Math.random()*(b-a+1))+a;
function question(t,table,level,op){let a,b,answer,label,hint,explanation,type='number',choices=null,kind,groups,items,dividend,remainder=0,jumps=[];
if(t===0||t===2&&op==='mul'){a=t===0?(table>=2&&table<=10?table:rnd(2,10)):(level?rnd(12,29):rnd(2,5));b=rnd(1,level?10:5);kind='multiply';groups=t===0?a:b;items=t===0?b:a;answer=a*b;label=`${a} × ${b} = ?`;hint=`Hay ${groups} grupos. Cada grupo tiene ${items} monedas. Cuenta un grupo a la vez y suma lo que llevas.`;explanation=`${groups} grupos de ${items}: ${Array.from({length:groups},()=>items).join(' + ')} = ${answer}. Por eso ${a} × ${b} = ${answer}.`;
if(t===0&&level&&rnd(0,2)===2){type='missing';answer=b;label=`${a} × ? = ${a*b}`;hint=`Hay ${a} cofres y ${a*b} monedas en total. Cuenta cuántas monedas hay en un solo cofre.`;explanation=`Cada cofre tiene ${b} monedas. Falta ${b}: ${a} × ${b} = ${a*b}.`;type='number';kind='missing'}
}else if(t===1){const minus=Math.random()<.5;if(!level){b=rnd(1,5);const units=minus?rnd(b,9):rnd(0,9-b);a=rnd(1,3)*10+units}else{a=rnd(21,79);b=rnd(11,29)}if(minus&&b>a)[a,b]=[b,a];kind=minus?'subtract':'add';answer=minus?a-b:a+b;label=`${a} ${minus?'−':'+'} ${b} = ?`;const parts=level?[Math.floor(b/10)*10,b%10].filter(Boolean):Array.from({length:b},()=>1);jumps=parts.map(n=>minus?-n:n);hint=`Empieza en ${a}. ${minus?'Retrocede':'Avanza'} ${b} ${b===1?'lugar':'lugares'}. Usa el botón para dar un salto a la vez.`;let value=a;explanation=jumps.map(n=>{const next=value+n,line=`${value} ${n<0?'−':'+'} ${Math.abs(n)} = ${next}`;value=next;return line}).join('. ')+'.';
}else{kind='divide';b=level?rnd(2,9):rnd(2,4);a=level?rnd(5,10):rnd(2,4);remainder=op==='rem'?rnd(1,b-1):0;dividend=a*b+remainder;answer=op==='rem'?`${a},${remainder}`:a;type=op==='rem'?'remainder':'number';label=`${dividend} ÷ ${b} = ?`;hint=`Reparte ${dividend} monedas entre ${b} animales. En cada ronda da una moneda a cada animal. Todos deben recibir lo mismo.`;explanation=`Cada animal recibe ${a} monedas${remainder?' y sobran '+remainder:' y no sobra ninguna'}. ${b} × ${a} = ${a*b}. ${dividend} − ${a*b} = ${remainder}.`;groups=b;items=a}
return {a,b,answer,label,hint,explanation,type,choices,kind,groups,items,dividend,remainder,jumps}}
let visualState={step:0};
function resetVisual(){visualState={step:0}}
function coinTokens(n){const tens=Math.floor(n/10),ones=n%10;return `<div class="token-row" aria-hidden="true">${Array.from({length:tens},()=>'<span class="ten-token">10</span>').join('')}${Array.from({length:ones},()=>'<span class="coin-token"></span>').join('')}</div>`}
function visualModel(q){const step=visualState.step;let html='';if(q.kind==='multiply'||q.kind==='missing'){html=`<div class="model-heading"><b>${q.groups} ${q.groups===1?'cofre':'cofres'}</b><span>×</span><b>${q.kind==='missing'?'¿cuántas?':q.items} ${q.items===1?'moneda':'monedas'} en cada cofre</b></div><div class="group-grid">${Array.from({length:q.groups},(_,i)=>`<div class="coffer ${i<step?'counted':''}"><div class="coffer-label">Cofre ${i+1} ${i<step?'✓':''}</div>${coinTokens(q.items)}<small>${q.items} ${q.items===1?'moneda':'monedas'}</small></div>`).join('')}</div><div class="model-caption">${q.items>=10?'La ficha azul vale 10 monedas. Cada ficha dorada vale 1.':'Cada ficha dorada representa una moneda.'}</div><div class="action-result" role="status">${step?`Contamos ${step} ${step===1?'cofre':'cofres'}: ${Array.from({length:step},()=>q.items).join(' + ')} = <b>${step*q.items}</b> monedas.`:'¿Cuántas monedas hay entre todos los cofres? Cuenta uno a la vez.'}</div><button class="soft" ${step>=q.groups?'disabled':''} onclick="advanceVisual()">${step?'Contar otro cofre':'Contar el primer cofre'} →</button>`
}else if(q.kind==='divide'){const rounds=Math.min(step,q.items),used=rounds*q.groups,left=q.dividend-used;html=`<div class="model-heading"><b>${q.dividend} monedas</b><span>÷</span><b>${q.groups} animales</b></div><div class="pool"><span>Por repartir: <strong>${left}</strong></span>${coinTokens(left)}</div><div class="group-grid">${Array.from({length:q.groups},(_,i)=>`<div class="coffer ${rounds?'counted':''}"><div class="coffer-label">${['🐢','🐈','🐒','🦜','🐬','🐻','🐰','🦊','🐼'][i]} Animal ${i+1}</div>${coinTokens(rounds)}<small>${rounds} ${rounds===1?'moneda':'monedas'}</small></div>`).join('')}</div><div class="action-result" role="status">${rounds===q.items?`Todos recibieron <b>${q.items}</b>. ${q.remainder?'Sobran '+q.remainder+' monedas: no alcanzan para otra ronda completa.':'¡No sobró ninguna moneda!'}`:'Da una moneda a cada animal en cada ronda. Así nadie recibe más que los demás.'}</div><button class="soft" ${rounds===q.items?'disabled':''} onclick="advanceVisual()">Repartir una ronda →</button>`
}else{let value=q.a;const nodes=[q.a];q.jumps.forEach(n=>{value+=n;nodes.push(value)});const dx=600/Math.max(1,q.jumps.length),x=i=>q.kind==='subtract'?640-i*dx:40+i*dx;html=`<div class="model-heading"><b>Empieza en ${q.a}</b><span>${q.kind==='add'?'→ Avanza':'← Retrocede'}</span></div><div class="number-track" role="img" aria-label="Camino de saltos desde ${q.a}"><svg viewBox="0 0 680 150" aria-hidden="true"><path d="M40 105H640" stroke="#91b9aa" stroke-width="4"/>${nodes.map((n,i)=>`<circle cx="${x(i)}" cy="105" r="${i===step?15:8}" fill="${i<=step?'#235c55':'#d4dfd5'}"/><text x="${x(i)}" y="143" text-anchor="middle" fill="#173f43" font-size="22">${i<=step?n:'?'}</text>${i<q.jumps.length?`<path d="M${x(i)} 85Q${x(i+.5)} 10 ${x(i+1)} 85" fill="none" stroke="${i<step?'#bd7336':'#cfd9cb'}" stroke-width="3"/><text x="${x(i+.5)}" y="35" text-anchor="middle" fill="#173f43" font-size="18">${q.jumps[i]>0?'+':'−'}${Math.abs(q.jumps[i])}</text>`:''}`).join('')}</svg></div><div class="action-result" role="status">${step?`Salto ${step}: ${nodes[step-1]} ${q.jumps[step-1]>0?'+':'−'} ${Math.abs(q.jumps[step-1])} = <b>${nodes[step]}</b>.`:`${q.kind==='add'?'Sumar es avanzar y juntar.':'Restar es retroceder o quitar.'} Da el primer salto.`}</div><button class="soft" ${step>=q.jumps.length?'disabled':''} onclick="advanceVisual()">Dar un salto →</button>`}
return `<div class="learning-model">${html}<button class="outline" style="margin-left:8px" onclick="resetVisual();paintVisual()">Volver a mirar desde el inicio</button></div>`}
function currentVisualQuestion(){return mission.stage===0?mission.demoQ:mission.stage===1?mission.guideQ:mission.questions[mission.index]}
function paintVisual(){const q=currentVisualQuestion();$('#visual-model').innerHTML=visualModel(q)}
function advanceVisual(){const q=currentVisualQuestion(),max=q.kind==='divide'?q.items:q.kind==='multiply'||q.kind==='missing'?q.groups:q.jumps.length;if(visualState.step>=max)return;visualState.step++;if(mission.stage===2)mission.hinted=true;paintVisual();if(audioPrefs.auto){let words=q.kind==='divide'?`Ronda ${visualState.step}. Cada animal tiene ${visualState.step} monedas. Quedan ${q.dividend-visualState.step*q.groups} por repartir.`:q.kind==='multiply'||q.kind==='missing'?`Contamos ${visualState.step} cofres. Llevamos ${visualState.step*q.items} monedas.`:`Llegamos al número ${q.a+q.jumps.slice(0,visualState.step).reduce((a,b)=>a+b,0)}.`;narrate(words)}}
function questionPrompt(q){if(q.kind==='missing')return `En ${q.groups} cofres hay ${q.a*q.b} monedas en total. ¿Cuántas monedas hay en cada cofre?`;if(q.kind==='multiply')return `Hay ${q.groups} ${q.groups===1?'cofre':'cofres'} con ${q.items} ${q.items===1?'moneda':'monedas'} en cada uno. ¿Cuántas monedas hay en total?`;if(q.kind==='divide')return `Tenemos ${q.dividend} monedas para ${q.groups} animales. ¿Cuántas recibe cada uno${q.remainder?' y cuántas sobran':''}?`;return q.kind==='add'?`Tienes ${q.a} monedas y encuentras ${q.b} más. ¿Cuántas tienes ahora?`:`Tienes ${q.a} monedas y usas ${q.b}. ¿Cuántas te quedan?`}
function conceptText(q){return q.kind==='divide'?'Repartir la misma cantidad a cada animal':q.kind==='multiply'||q.kind==='missing'?'Sumar lo que hay en los grupos iguales':q.kind==='add'?'Avanzar para juntar más monedas':'Retroceder para quitar monedas'}
function checkConcept(correct){$('#concept-feedback').textContent=correct?'¡Eso es! Ya sabes por qué usamos esta operación. Ahora vamos a intentarlo con un ejemplo nuevo.':'Mira el dibujo y piensa qué necesitamos: ¿juntar, quitar o repartir por igual? Intenta de nuevo.';if(correct)$('#begin-chest').hidden=false;if(audioPrefs.auto)narrate($('#concept-feedback').textContent)}

let selectedTable=null;
function shuffled(list){const out=[...list];for(let i=out.length-1;i>0;i--){const j=rnd(0,i);[out[i],out[j]]=[out[j],out[i]]}return out}
function tableQuestion(table,factor,withOptions=false){const answer=table*factor;const distractors=[answer-table,answer+table,answer+1,answer+2*table].filter(n=>n>0&&n!==answer);const options=shuffled([answer,...[...new Set(distractors)].slice(0,2)]);return {a:table,b:factor,answer,label:`${table} × ${factor} = ?`,kind:'multiply',groups:table,items:factor,type:withOptions?'choice':'number',choices:withOptions?options:null,hint:`Son ${table} cofres con ${factor} monedas en cada uno. Suma ${factor} una vez por cada cofre.`,explanation:`${table} × ${factor} = ${answer}. ${Array.from({length:table},()=>factor).join(' + ')} = ${answer}.`}}
function chooseTableIsland(){selectedTable=null;$('#app').innerHTML=`<section class="mission"><button class="soft" onclick="page('map')">← Volver al mapa</button><div class="card" style="margin-top:20px"><div class="eyebrow">ISLA DE LAS TABLAS</div><h1>¿Qué tabla quieres practicar?</h1><p class="lesson-instruction">Elige una tabla. Primero la practicaremos en orden. Después te preguntaré esa misma tabla en orden salteado.</p><div class="table-picker">${Array.from({length:9},(_,i)=>`<button class="table-tile" id="table-tile-${i+2}" onclick="selectTable(${i+2})" aria-pressed="false"><span>Tabla del</span><strong>${i+2}</strong></button>`).join('')}</div><div class="teaching-note"><b>Así será tu aventura</b><p>1. Elige tu tabla.<br>2. Responde tu tabla en orden, desde × 1 hasta × 10.<br>3. Responde 10 preguntas salteadas. Cada una tiene 3 opciones.</p></div><p id="selected-table-note" role="status">Toca la tabla que quieras repasar.</p><button id="start-table" class="gold" disabled onclick="startTableSession()">Practicar la tabla elegida →</button></div></section>`;window.scrollTo(0,0)}
function selectTable(n){if(!Number.isInteger(n)||n<2||n>10)return;selectedTable=n;for(let i=2;i<=10;i++){const el=$('#table-tile-'+i);el.classList.toggle('chosen-table',i===n);el.setAttribute('aria-pressed',String(i===n))}$('#selected-table-note').textContent=`Elegiste la tabla del ${n}. ¡Vamos a practicarla juntas!`;$('#start-table').disabled=false;$('#start-table').textContent=`Practicar la tabla del ${n} →`}
function startTableSession(){if(!selectedTable||selectedTable<2||selectedTable>10)return;let factors=shuffled(Array.from({length:10},(_,i)=>i+1));if(factors.every((v,i)=>v===i+1))factors.push(factors.shift());mission={id:newId(),topic:0,table:selectedTable,level:0,op:'mul',review:false,stage:1,practiceIndex:0,practiceSeen:false,index:0,questions:factors.map(n=>tableQuestion(selectedTable,n,true)),first:0,help:0,wrong:0,errors:[],attempts:0,hinted:false,answered:false};tablePractice()}
function tablePractice(){mission.stage=1;mission.practiceSeen=false;mission.practiceAttempts=0;mission.guideQ=tableQuestion(mission.table,mission.practiceIndex+1);const q=mission.guideQ;shell(`<div class="eyebrow">TABLA DEL ${mission.table} · PRÁCTICA ${mission.practiceIndex+1} DE 10</div><h2>Practica en orden</h2><div class="progress"><i style="width:${mission.practiceIndex/10*100}%"></i></div><p>Escribe el resultado y pulsa “Comprobar”.</p><form id="table-practice-form"><label class="direct-table-equation" for="table-practice-input"><span>${q.a} × ${q.b} =</span><input id="table-practice-input" type="number" min="0" step="1" inputmode="numeric" required autocomplete="off" aria-label="Resultado de ${q.a} por ${q.b}" placeholder="?"></label><button id="check-table-practice" class="gold" type="submit">Comprobar</button><button id="show-table-result" class="outline" type="button" onclick="revealTablePractice()">Ver respuesta</button></form><div id="table-practice-answer" class="feedback" role="status" hidden></div><button class="gold" id="next-table-practice" hidden style="margin-top:20px" onclick="nextTablePractice()">${mission.practiceIndex===9?'Comenzar reto salteado →':'Siguiente →'}</button>`);$('#table-practice-form').onsubmit=e=>{e.preventDefault();checkTablePractice()};$('#table-practice-input').focus()}
function checkTablePractice(){if(!mission||mission.topic!==0||mission.stage!==1||mission.practiceSeen)return;const input=$('#table-practice-input');if(input.value.trim()===''||!Number.isInteger(Number(input.value)))return;mission.practiceAttempts++;const q=mission.guideQ;$('#table-practice-answer').hidden=false;if(Number(input.value)===q.answer){mission.practiceSeen=true;$('#table-practice-answer').textContent=`¡Correcto! ${q.a} × ${q.b} = ${q.answer}.`;input.disabled=true;$('#check-table-practice').disabled=true;$('#show-table-result').disabled=true;$('#next-table-practice').hidden=false;$('#next-table-practice').focus();if(audioPrefs.auto)narrate(`¡Correcto! ${q.a} por ${q.b} es igual a ${q.answer}.`)}else{$('#table-practice-answer').textContent='Todavía no. Intenta otra vez o pulsa “Ver respuesta” para repasarla.';if(audioPrefs.auto)narrate('Intenta otra vez. Si no la recuerdas, puedes ver la respuesta.');input.select()}}
function revealTablePractice(){if(!mission||mission.topic!==0||mission.stage!==1||mission.practiceSeen)return;const q=mission.guideQ;$('#table-practice-answer').hidden=false;$('#table-practice-answer').textContent=`${q.a} × ${q.b} = ${q.answer}. Escribe ${q.answer} y pulsa “Comprobar” para practicarla.`;if(audioPrefs.auto)narrate(`${q.a} por ${q.b} es igual a ${q.answer}. Ahora escribe el resultado.`);$('#table-practice-input').focus()}
function nextTablePractice(){if(!mission.practiceSeen)return;if(mission.practiceIndex<9){mission.practiceIndex++;tablePractice()}else{mission.stage=2;mission.index=0;tableQuiz()}}
function tableQuiz(){const q=mission.questions[mission.index];mission.stage=2;mission.attempts=0;mission.hinted=false;mission.answered=false;shell(`<div class="row between"><span class="eyebrow">RETO SALTEADO · ${mission.index+1} DE 10</span><span class="badge">Tabla del ${mission.table}</span></div><div class="progress"><i style="width:${mission.index/10*100}%"></i></div><h2>Elige la respuesta correcta</h2><div class="quiz-operation">${q.a} × ${q.b} = <span>?</span></div><div id="answer-form"><div class="three-answers">${q.choices.map((n,i)=>`<button type="button" id="table-answer-${i}" onclick="pickTableAnswer(${i})"><small>Opción ${i+1}</small><strong>${n}</strong></button>`).join('')}</div></div><button class="outline" id="hint-btn" style="margin-top:20px" onclick="tableHint()">Ver una pista</button><div id="feedback" class="feedback" role="status"></div><button id="next" class="gold" hidden style="margin-top:20px" onclick="nextQuestion()">${mission.index===9?'Ver mis resultados →':'Siguiente pregunta →'}</button>`)}
function tableArithmeticHint(q){return q.b===1?`${q.a} × 1 = ${q.a}. Multiplicar por 1 deja el mismo número.`:`Recuerda: ${q.a} × ${q.b-1} = ${q.a*(q.b-1)}. Suma ${q.a} más para encontrar ${q.a} × ${q.b}.`}
function pickTableAnswer(index){if(!mission||mission.topic!==0||mission.stage!==2||mission.answered||!Number.isInteger(index)||index<0||index>2)return;const q=mission.questions[mission.index],value=q.choices[index],button=$('#table-answer-'+index);if(button.disabled)return;mission.attempts++;if(value===q.answer){mission.answered=true;if(mission.attempts===1&&!mission.hinted)mission.first++;else mission.help++;$('#feedback').textContent=`¡Correcto! ${q.a} × ${q.b} = ${q.answer}.`;for(let i=0;i<3;i++)$('#table-answer-'+i).disabled=true;button.classList.add('answer-correct');$('#hint-btn').disabled=true;$('#next').hidden=false}else{if(mission.attempts===1){mission.wrong++;mission.errors.push(q.label)}mission.hinted=true;button.disabled=true;button.classList.add('answer-retry');$('#feedback').textContent='Intenta otra vez. '+tableArithmeticHint(q)}if(audioPrefs.auto)narrate($('#feedback').textContent)}
function tableHint(){if(!mission||mission.topic!==0||mission.stage!==2||mission.answered)return;mission.hinted=true;const text=tableArithmeticHint(mission.questions[mission.index]);$('#feedback').textContent=text;if(audioPrefs.auto)narrate(text)}

function start(t,review){if(t===0)return startTableSession();if(review&&!state.missions.some(m=>m.topic===t&&m.wrong>0)){toast('Todavía no hay errores pendientes en este tema. Comienza una misión.');return}const table=Number($('#table')?.value||2),level=Number($('#level')?.value||0),op=$('#operation')?.value||'mul';mission={id:newId(),topic:t,table,level,op,review,stage:0,index:0,questions:Array.from({length:5},()=>question(t,table,level,op)),first:0,help:0,wrong:0,errors:[],attempts:0,hinted:false,answered:false};intro()}
function shell(body){stopNarration();$('#app').innerHTML=`<section class="mission"><button class="soft" onclick="page('map')">← Volver al mapa</button><div class="steps">${(mission.topic===0?['1 · Elige tu tabla','2 · Practica en orden','3 · Reto salteado']:['1 · Descubre','2 · Practica conmigo','3 · Abre el cofre']).map((x,i)=>`<span class="${mission.stage===i?'current':''}">${x}</span>`).join('')}</div><div class="card"><div class="voice-tools"><button class="outline" onclick="narrateLesson()">🔊 Escuchar explicación</button><button class="soft" onclick="pauseNarration()">Pausar voz</button><button class="soft" onclick="resumeNarration()">Reanudar voz</button></div><div id="lesson-content">${body}</div></div></section>`;window.scrollTo(0,0);if(audioPrefs.auto&&mission.topic!==3){if(mission.stage===2){const q=mission.questions[mission.index];narrate(mission.topic===0?`¿Cuánto es ${q.a} por ${q.b}? Elige una de las tres respuestas.`:questionPrompt(q));}else if(mission.topic===0){const q=mission.guideQ;narrate(`Practiquemos la tabla del ${mission.table}. ¿Cuánto es ${q.a} por ${q.b}? Escribe el resultado y pulsa Comprobar.`)}else narrateLesson()}}
function intro(){mission.demoQ=question(mission.topic,mission.table,0,mission.op);resetVisual();const q=mission.demoQ;shell(`<div class="eyebrow">PRIMERO: ENTIENDE LA IDEA</div><h2>${q.kind==='divide'?'Dividir es repartir por igual':q.kind==='multiply'||q.kind==='missing'?'Multiplicar es juntar grupos iguales':q.kind==='add'?'Sumar es juntar':'Restar es quitar'}</h2><p class="lesson-instruction">${questionPrompt(q)}</p><div id="visual-model">${visualModel(q)}</div><div class="teaching-note"><b>Mira → Toca → Explica</b><p>Usa el botón del dibujo. Observa qué cambia. Luego cuéntale a tu acompañante qué hiciste.</p></div><button class="gold" onclick="guided()">Ya vi la idea · Vamos juntas →</button>`)}
function guided(){mission.stage=1;mission.guideQ=question(mission.topic,mission.table,mission.level,mission.op);resetVisual();const q=mission.guideQ;const options=[{ok:true,text:conceptText(q)},{ok:false,text:q.kind==='divide'?'Darle todas las monedas a un solo animal':q.kind==='subtract'?'Juntar más monedas':'Quitar monedas sin contar'}].sort(()=>Math.random()-.5);shell(`<div class="eyebrow">AHORA: LO HACEMOS JUNTAS</div><h2>Un paso a la vez</h2><p class="lesson-instruction">${questionPrompt(q)}</p><div class="equation-pair"><span>Así lo escribimos</span><b>${q.label}</b></div><div id="visual-model">${visualModel(q)}</div><button class="outline" style="margin-top:20px" onclick="$('#guide-answer').hidden=false;if(audioPrefs.auto)narrate(mission.guideQ.explanation)">Ver cómo queda la operación</button><div id="guide-answer" class="feedback" hidden>${q.explanation}</div><h3 style="margin-top:28px">¿Qué estamos haciendo?</h3><p>Elige la idea que explica el dibujo.</p><div class="options">${options.map(x=>`<button onclick="checkConcept(${x.ok})">${x.text}</button>`).join('')}</div><div id="concept-feedback" class="feedback" role="status"></div><button class="gold" id="begin-chest" hidden onclick="mission.stage=2;exercise()" style="margin-top:18px">¡Ahora lo intento yo! →</button>`)}
function exercise(){if(mission.topic===0)return tableQuiz();const q=mission.questions[mission.index];mission.attempts=0;mission.hinted=false;mission.answered=false;resetVisual();shell(`<div class="row between"><span class="eyebrow">TU TURNO · RETO ${mission.index+1} DE 5</span><span>${state.avatar} Paso a paso</span></div><div class="progress"><i style="width:${mission.index/5*100}%"></i></div><h2>${q.kind==='divide'?'Ayuda a repartir el tesoro':q.kind==='multiply'||q.kind==='missing'?'Cuenta los tesoros':'Sigue el camino de las monedas'}</h2><p class="lesson-instruction">${questionPrompt(q)}</p><div id="visual-model">${visualModel(q)}</div><div class="equation-pair"><span>La operación del dibujo</span><b>${q.label}</b></div><form id="answer-form"><label for="answer">${q.type==='remainder'?'¿Cuántas monedas recibe cada animal?':q.kind==='missing'?'¿Cuántas monedas tiene un cofre?':q.kind==='divide'?'¿Cuántas monedas recibe cada animal?':'¿Cuántas monedas son?'}</label><input class="answer" id="answer" type="number" inputmode="numeric" min="0" step="1" required placeholder="Escribe aquí">${q.type==='remainder'?'<label for="remainder">¿Cuántas monedas sobran sin repartir?</label><input class="answer" id="remainder" type="number" min="0" step="1" inputmode="numeric" required placeholder="Sobran…">':''}<button type="submit" style="margin:12px">Revisar mi respuesta</button></form><p class="small muted">Puedes contar con el dibujo. Usar los botones se registra como apoyo; no quita monedas.</p><div class="row"><button class="outline" id="hint-btn" onclick="hint()">💡 Muéstrame un paso</button><button class="soft" id="explain-btn" onclick="explain()" hidden>Ver la explicación completa</button></div><div id="feedback" class="feedback" role="status"></div><button id="next" class="gold" style="margin-top:20px" hidden onclick="nextQuestion()">Otro reto →</button>`);$('#answer-form').onsubmit=e=>{e.preventDefault();checkAnswer($('#answer').value+(q.type==='remainder'?','+$('#remainder').value:''))}}
function hint(){mission.hinted=true;const q=mission.questions[mission.index];advanceVisual();$('#feedback').textContent=q.hint;if(audioPrefs.auto)narrate(q.hint)}

function checkAnswer(value){if(mission.answered)return;const q=mission.questions[mission.index];mission.attempts++;if(String(value).trim()===String(q.answer)){mission.answered=true;if(mission.attempts===1&&!mission.hinted)mission.first++;else mission.help++;$('#feedback').textContent='¡Lo lograste! '+q.explanation;$('#next').hidden=false;$('#hint-btn').disabled=true;$('#explain-btn').hidden=true;$('#answer-form').querySelectorAll('button,input').forEach(x=>x.disabled=true)}else{if(mission.attempts===1){mission.wrong++;mission.errors.push(q.label)}advanceVisual();$('#feedback').textContent='Vamos a mirar un paso juntas. '+q.hint+' Prueba de nuevo cuando estés lista.';mission.hinted=true;$('#explain-btn').hidden=false}if(audioPrefs.auto)narrate($('#feedback').textContent)}
function explain(){mission.answered=true;$('#feedback').textContent=mission.questions[mission.index].explanation+' Lo volveremos a practicar con otro ejercicio.';$('#next').hidden=false;$('#explain-btn').hidden=true;$('#answer-form').querySelectorAll('button,input').forEach(x=>x.disabled=true);if(audioPrefs.auto)narrate($('#feedback').textContent)}
function nextQuestion(){mission.index++;if(mission.index<mission.questions.length)exercise();else finishMission()}
function finishMission(){if(state.missions.some(m=>m.id===mission.id))return;let requested=state.settings.mission+mission.first*state.settings.first+mission.help*state.settings.help;if(mission.review&&!state.reviewDays.includes(day())){requested+=state.settings.review;state.reviewDays.push(day())}const earned=award(requested,mission.review?'Repaso completado':topics[mission.topic][1]);state.missions.push({id:mission.id,topic:mission.topic,day:day(),first:mission.first,help:mission.help,wrong:mission.wrong,errors:mission.errors,table:mission.topic===0?mission.table:null,title:mission.title||null});if(!state.days.includes(day()))state.days.push(day());let bonus=0;if(state.days.filter(d=>d>=week()).length>=3&&!state.weekly.includes(week())){bonus=award(state.settings.weekly,'Tres días de práctica');state.weekly.push(week())}save();$('#balance').textContent=state.coins;$('#app').innerHTML=`<section class="mission card"><div class="stars">✦ 🏴‍☠️ ✦</div><h1 style="text-align:center">¡Un nuevo logro, ${esc(state.name)}!</h1><p style="text-align:center">Cada intento te ayuda a aprender.</p><div class="stats"><div><strong>+${earned+bonus}</strong>monedas</div><div><strong>${mission.first}</strong>sin ayuda</div><div><strong>${mission.help}</strong>con apoyo</div><div><strong>${mission.questions.length-mission.first-mission.help}</strong>por reforzar</div></div>${mission.topic===3?`<label for="rating">Para el adulto: ¿cómo leyó?</label><select id="rating" onchange="state.readRatings['${mission.id}']=this.value;save()"><option value="">Sin valoración</option><option>Necesitó apoyo</option><option>Leyó con algunas pausas</option><option>Leyó con mayor seguridad</option></select>`:''}<p>${earnedToday()>=state.settings.cap?'Alcanzaste el máximo de monedas de hoy. Puedes descansar o seguir practicando sin sumar monedas.':'Tu cofre sigue creciendo. Elige cuándo continuar.'}</p><div class="row"><button class="gold" onclick="page('map')">Volver a mi mapa</button><button class="outline" onclick="page('rewards')">Ver mis tesoros</button></div></section>`}
const stories=[
{title:'El mapa de Lila',level:0,text:['Lila, la gata pirata, encontró un mapa dentro de una botella. Tenía una estrella dibujada junto a una palmera. Su amigo Coco quiso correr a buscar el tesoro, pero Lila prefirió observar la isla desde el barco.','Al bajar, contaron cinco palmeras. Solo una tenía una cinta azul. Bajo sus hojas encontraron una caja con semillas. Lila sonrió: podrían sembrarlas para que la isla tuviera más sombra. El tesoro ayudaría a todos los animales.'],word:'Observar',meaning:'Mirar con atención para descubrir detalles.',qs:[['¿Qué encontraron dentro de la caja?',['Semillas','Monedas','Una cinta'],0,'La caja contenía semillas para sembrar.'],['¿Qué hicieron antes de bajar?',['Observaron la isla','Abrieron la caja','Sembraron'],0,'Lila prefirió observar la isla desde el barco.'],['¿Por qué era útil el tesoro?',['Permitiría tener más sombra','Haría más rápido el barco','Daría agua al mar'],0,'Las semillas podrían convertirse en árboles y dar sombra.']]},
{title:'El puente de Tomás',level:0,text:['Tomás, la tortuga, quería cruzar un arroyo para visitar a sus amigos. El puente de madera tenía una tabla suelta. En lugar de pasar, colocó una rama frente a la entrada y buscó a la tripulación.','La monita Mara trajo una cuerda y el loro Coco encontró una tabla firme. Juntos repararon el puente. Después cruzaron despacio para comprobar que fuera seguro. Tomás llegó más tarde, pero sus amigos lo esperaron con fruta. Todos celebraron haber trabajado en equipo.'],word:'Reparar',meaning:'Arreglar algo que estaba dañado.',qs:[['¿Qué problema tenía el puente?',['Una tabla suelta','No tenía cuerda','Estaba bajo el mar'],0,'El texto dice que tenía una tabla suelta.'],['¿Quién trajo una cuerda?',['Mara','Tomás','Coco'],0,'La monita Mara llevó la cuerda.'],['¿Por qué Tomás buscó ayuda?',['Para cruzar con seguridad','Para ganar una carrera','Para esconder la fruta'],0,'El puente necesitaba una reparación antes de cruzar.']]},
{title:'Una luz en el mar',level:0,text:['Al caer la tarde, Delfi vio una luz cerca de unas rocas. Pensó que era otro barco y se acercó despacio. Allí encontró a Coco con una linterna. El loro buscaba su sombrero, que el viento había llevado hasta una pequeña playa.','Delfi no podía caminar en la arena. Entonces llamó a Lila, que llegó en un bote. La gata recogió el sombrero y lo devolvió. Coco agradeció la ayuda y guardó su linterna antes de regresar con sus amigos.'],word:'Linterna',meaning:'Objeto portátil que ilumina lugares oscuros.',qs:[['¿De quién era la luz?',['De Coco','De Lila','De otro barco'],0,'Coco llevaba una linterna.'],['¿Qué había perdido Coco?',['Su sombrero','Su mapa','Su bote'],0,'El viento había llevado su sombrero a la playa.'],['¿Por qué llamaron a Lila?',['Podía recoger el sombrero en la arena','Tenía otra linterna','Conocía al viento'],0,'Delfi no podía caminar en la arena y necesitaba ayuda.']]},
{title:'El huerto de la tripulación',level:1,text:['En la isla del Faro, la tripulación decidió plantar un huerto. Mara propuso sembrar todo en una sola tarde. Tomás sugirió revisar primero el terreno: algunas zonas recibían mucha luz y otras permanecían bajo los árboles.','Lila dibujó un plano. Colocaron los tomates en el lugar soleado y reservaron un rincón para guardar las herramientas. Coco escribió pequeños letreros para recordar qué habían sembrado. Cada animal eligió un día para revisar la tierra y regar cuando fuera necesario.','Una semana después, todavía no había tomates. Mara se sintió decepcionada, pero Tomás le mostró un brote verde. Comprendieron que un huerto necesita tiempo y cuidado. Decidieron anotar los cambios cada semana, en lugar de desenterrar las semillas para ver si crecían.'],word:'Brote',meaning:'Parte nueva de una planta que empieza a crecer.',qs:[['¿Dónde colocaron los tomates?',['En el lugar soleado','Bajo las herramientas','Dentro del barco'],0,'El plano reservó el lugar soleado para los tomates.'],['¿Qué hicieron para identificar lo sembrado?',['Escribieron letreros','Desenterraron las semillas','Pintaron las hojas'],0,'Coco escribió pequeños letreros.'],['¿Qué aprendió la tripulación?',['Que crecer requiere tiempo y cuidado','Que las plantas crecen en una tarde','Que no hacía falta regar'],0,'El brote mostró un avance, aunque aún no hubiera tomates.']]},
{title:'La biblioteca del faro',level:1,text:['Durante una tormenta, los animales se refugiaron en el viejo faro. Mientras esperaban, Lila abrió un armario y encontró libros cubiertos de polvo. Había relatos de viajes, poemas y un libro sobre las estrellas. Algunos tenían las páginas dobladas, pero todavía podían leerse.','La tripulación decidió organizar una pequeña biblioteca. Limpiaron los estantes y separaron los libros por temas. Mara preparó una libreta para anotar quién se llevaba cada libro y cuándo pensaba devolverlo. Coco colocó una lámpara junto a una silla cómoda.','Tomás eligió el libro de estrellas. Le costaban algunas palabras y pidió leer por turnos con Lila. Al terminar una página, conversaban sobre lo que habían entendido. Cuando dejó de llover, nadie quiso salir enseguida: habían encontrado otra forma de viajar sin abandonar el faro.'],word:'Refugiarse',meaning:'Buscar protección en un lugar seguro.',qs:[['¿Por qué entraron al faro?',['Para protegerse de una tormenta','Para comprar libros','Para buscar monedas'],0,'Se refugiaron allí durante una tormenta.'],['¿Cómo practicó Tomás la lectura?',['Leyendo por turnos con Lila','Sin abrir el libro','Repitiendo solo el título'],0,'Tomás pidió leer por turnos y conversar sobre lo leído.'],['¿Qué significa viajar sin abandonar el faro?',['Imaginar lugares mediante los libros','Mover el faro por el mar','Salir cuando llueve'],0,'Los relatos permiten conocer e imaginar otros lugares.']]},
{title:'La playa de las conchas',level:1,text:['La tripulación planeaba pasar la tarde en una playa de arena clara. Llevaron agua, fruta y una manta. Al llegar, encontraron envolturas cerca de las rocas y una bolsa atrapada entre unas ramas. Delfi explicó que la marea podía arrastrar esos residuos al mar.','Antes de jugar, los animales buscaron un recipiente para reunir la basura. Lila y Mara recogieron las envolturas con guantes. Tomás apartó al grupo de un objeto cortante y pidió ayuda a una persona encargada de cuidar la playa. Coco preparó un letrero: “Lleva tus residuos contigo”.','Después disfrutaron su picnic y observaron conchas sin llevárselas. Al salir revisaron que no quedara ninguna de sus cosas. La playa estaba más limpia y ellos habían aprendido que cuidar un lugar también forma parte de disfrutarlo.'],word:'Residuos',meaning:'Materiales que se desechan después de usarlos.',qs:[['¿Qué podía llevar la marea al mar?',['Los residuos','La manta del barco','El faro'],0,'Delfi explicó que la marea podía arrastrar los residuos.'],['¿Qué hicieron ante un objeto cortante?',['Se apartaron y pidieron ayuda','Lo tocaron sin protección','Lo escondieron'],0,'Tomás apartó al grupo y pidió ayuda.'],['¿Cuál es la idea principal?',['Disfrutar la playa también implica cuidarla','Hay que llevarse todas las conchas','Solo se puede jugar en un barco'],0,'La tripulación limpió y revisó el lugar antes de irse.']]}
];
function chooseReading(){$('#app').innerHTML=`<section class="mission"><button class="soft" onclick="page('map')">← Volver al mapa</button><div class="card" style="margin-top:20px"><div class="eyebrow">BAHÍA DE LAS HISTORIAS</div><h1>Una historia, un nuevo mundo</h1><p>Lee por partes. Puedes pedir ayuda con las palabras y volver al texto.</p><div class="reading-list">${stories.map((s,i)=>`<button onclick="startReading(${i})">${i<3?'🐚':'📖'} ${s.title}<br><small>${i<3?'Lectura corta':'Un paso más'} · ${s.text.join(' ').split(/\s+/).length} palabras</small></button>`).join('')}</div></div></section>`}
function startReading(i){reading={id:i,paragraph:0,size:22,step:'read'};mission={id:newId(),topic:3,stage:0,questions:stories[i].qs,index:0,first:0,help:0,wrong:0,errors:[],title:stories[i].title,attempts:0,hinted:false,answered:false};renderReading()}
const storyScenes=[
[['🐈','🍾','🗺️','🌴'],['🐈','🌴','📦','🌱']],
[['🐢','🌊','🪵','⚠️'],['🐒','🦜','🪢','🌉']],
[['🐬','🌅','🔦','🦜'],['⛵','🐈','🏝️','🎩']],
[['🐒','🐢','☀️','🌳'],['🐈','🗺️','🍅','🏷️'],['🌱','📒','🐢','🕰️']],
[['⛈️','🐈','🗼','📚'],['🐒','📒','🪑','💡'],['🐢','🐈','📖','⭐']],
[['🏝️','🧺','🐬','🛍️'],['🐈','🐒','🧤','🗑️'],['🧺','🐚','🏝️','✨']]
];
function sceneMarkup(id,paragraph){return `<div class="story-scene" aria-hidden="true">${(storyScenes[id][paragraph]||storyScenes[id][0]).map(x=>`<span>${x}</span>`).join('<span style="font-size:18px;color:#729180">→</span>')}</div>`}
function readingSentences(){return stories[reading.id].text[reading.paragraph].match(/[^.!?]+[.!?]?/g)?.map(s=>s.trim()).filter(Boolean)||[]}
function renderReading(){const s=stories[reading.id];if(reading.sentence===undefined)reading.sentence=0;const sentences=readingSentences();shell(`<div class="eyebrow">LECTURA · PARTE ${reading.paragraph+1} DE ${s.text.length}</div><h2>${s.title}</h2>${sceneMarkup(reading.id,reading.paragraph)}<div class="reading-hint"><b>1. Mira la escena. 2. Lee lo que está en amarillo. 3. Cuenta qué pasó.</b><p>Lee una oración a la vez. Cuando estés lista, pulsa “Siguiente oración”. Puedes escucharla si necesitas apoyo.</p></div><div class="row" style="margin-top:16px"><button class="soft" onclick="reading.size=Math.max(18,reading.size-2);renderReading()" aria-label="Reducir letra">A−</button><button class="soft" onclick="reading.size=Math.min(34,reading.size+2);renderReading()" aria-label="Aumentar letra">A+</button><button class="outline" onclick="readCurrentSentence()">🔊 Escuchar esta oración</button><button class="soft" onclick="speechStop()">Detener voz</button></div><p class="reading" style="font-size:${reading.size}px">${sentences.map((line,i)=>`<span class="${i===reading.sentence?'sentence-active':'sentence-rest'}">${line}</span>`).join(' ')}</p><div class="row"><button class="outline" ${reading.sentence===0?'disabled':''} onclick="speechStop();reading.sentence--;renderReading()">← Oración anterior</button><button class="gold" ${reading.sentence>=sentences.length-1?'disabled':''} onclick="speechStop();reading.sentence++;renderReading()">Siguiente oración →</button><span class="pill">${reading.sentence+1} de ${sentences.length}</span></div><div class="feedback"><b>Una palabra para descubrir: ${s.word}.</b> ${s.meaning}</div><div class="teaching-note"><b>Cuéntalo con tus palabras</b><p>¿Quién aparece? ¿Qué hizo? ¿Qué pasó después? Puedes responder en voz alta a tu acompañante; la página no graba tu voz.</p></div><div class="row" style="margin-top:22px"><button class="outline" ${reading.paragraph===0?'disabled':''} onclick="speechStop();reading.paragraph--;reading.sentence=0;renderReading()">← Parte anterior</button>${reading.paragraph<s.text.length-1?'<button class="gold" onclick="speechStop();reading.paragraph++;reading.sentence=0;renderReading()">Ya entendí esta parte →</button>':'<button class="gold" onclick="speechStop();mission.stage=2;readingQuestion()">Vamos a comprender la historia →</button>'}</div><p class="small muted">No hay prisa. Puedes volver a leer todas las veces que necesites.</p>`)}
function readCurrentSentence(){narrate(readingSentences()[reading.sentence]||'')}

function speechStop(){stopNarration()}
function speak(){narrate(stories[reading.id].text[reading.paragraph])}
function readingFocus(question){if(question.startsWith('¿Por qué')||question.includes('significa')||question.includes('idea principal'))return 'Piensa en lo que pasó y en la razón. Puedes unir dos pistas de la historia.';if(question.startsWith('¿Quién')||question.startsWith('¿De quién'))return 'Busca el nombre del personaje que hizo esa acción.';return 'Busca la parte de la historia donde ocurre lo que pregunta.'}
function readingQuestion(){const q=mission.questions[mission.index];mission.attempts=0;mission.hinted=false;mission.answered=false;const choices=q[1].map((text,i)=>({text,i})).sort(()=>Math.random()-.5);shell(`<div class="eyebrow">COMPRENDER · PREGUNTA ${mission.index+1} DE 3</div><h2>${q[0]}</h2><div class="reading-hint">${readingFocus(q[0])}</div><p>Lee las opciones y elige una. Volver a la historia también es aprender.</p><div class="options" id="reading-options">${choices.map((x,i)=>`<button onclick="checkReading(${x.i})"><span class="option-symbol">${i+1}</span> ${x.text}</button>`).join('')}</div><button class="outline" onclick="mission.hinted=true;$('#reread').hidden=false;if(audioPrefs.auto)narrate(readingFocus(mission.questions[mission.index][0]))">📖 Buscar una pista en la historia</button><div id="reread" class="reading" style="font-size:20px" hidden>${sceneMarkup(reading.id,0)}${stories[reading.id].text.map(p=>'<p>'+p+'</p>').join('')}</div><div class="feedback" id="feedback" role="status"></div><button class="gold" id="next" hidden onclick="mission.index++;if(mission.index<3)readingQuestion();else finishMission()" style="margin-top:18px">Continuar →</button>`);if(audioPrefs.auto)narrate(q[0]+'. '+readingFocus(q[0]))}

function checkReading(n){if(mission.answered)return;const q=mission.questions[mission.index];mission.attempts++;if(n===q[2]){mission.answered=true;if(mission.attempts===1&&!mission.hinted)mission.first++;else mission.help++;$('#feedback').textContent='¡Muy bien! '+q[3];$('#reading-options').querySelectorAll('button').forEach(b=>b.disabled=true);$('#next').hidden=false;if(audioPrefs.auto)narrate('¡Muy bien! '+q[3])}else{if(mission.attempts===1){mission.wrong++;mission.errors.push(q[0])}mission.hinted=true;$('#feedback').textContent='Revisa el texto y prueba otra vez. Busca la parte que habla de esta pregunta.';$('#reread').hidden=false}}
function rewards(){$('#app').innerHTML=`<div class="eyebrow">LOS MEJORES TESOROS SE COMPARTEN</div><h1>Tesoros en familia</h1><p class="muted">Elige una meta y sueña tu próxima aventura en familia.</p><div class="row" style="margin-bottom:25px"><span class="coins">🪙 ${state.coins} disponibles</span><span class="pill">${state.claims.filter(c=>['solicitado','aprobado','programado'].includes(c.status)).reduce((a,c)=>a+c.cost,0)} reservadas o comprometidas</span></div><div class="grid">${state.rewards.map(r=>`<div class="card reward"><div class="row between"><span class="reward-icon">${r.icon}</span>${state.goal===r.id?'<span class="badge">★ Mi meta</span>':''}</div><h3>${esc(r.name)}</h3><strong>${r.cost} monedas</strong><p class="small muted">${esc(r.condition)||'Una experiencia para disfrutar juntos.'}</p><div class="progress"><i style="width:${Math.min(100,state.coins/r.cost*100)}%"></i></div><span class="small">${r.enabled?'Habilitado por tu familia':'Tu familia debe habilitar este tesoro'}</span><div class="row"><button class="outline" onclick="state.goal=${r.id};save();rewards()">Elegir meta</button><button class="gold" ${!r.enabled||state.coins<r.cost?'disabled':''} onclick="claim(${r.id})">Solicitar</button></div></div>`).join('')}</div><h2>Mis experiencias</h2>${claimsHtml(false)}<p class="notice">Las monedas no tienen valor monetario. Las salidas dependen de la organización familiar; solicitar un premio no reserva ni compra ninguna actividad.</p>`}
function claim(id){const r=state.rewards.find(x=>x.id===id);if(!r?.enabled||state.coins<r.cost)return;if(!confirm(`¿Solicitar ${r.name} por ${r.cost} monedas? Se reservarán hasta que tu familia responda.`))return;state.coins-=r.cost;state.claims.push({id:newId(),name:r.name,cost:r.cost,status:'solicitado',date:'',day:day(),returned:false});state.ledger.push({day:day(),amount:-r.cost,label:'Reserva: '+r.name,kind:'reserve'});save();$('#balance').textContent=state.coins;rewards();toast('¡Solicitud enviada al panel familiar! Pendiente de aprobación.')}
function claimsHtml(manage){if(!state.claims.length)return '<div class="card muted">Aquí aparecerán las experiencias que solicites.</div>';return state.claims.slice().reverse().map(c=>`<div class="card" style="margin-bottom:12px"><div class="row between"><b>${esc(c.name)} · ${c.cost} 🪙</b><span class="pill">${c.status==='solicitado'?'Pendiente de aprobación':c.status}</span></div>${c.date?'<p>Fecha acordada: '+esc(c.date)+'</p>':''}${manage&&!['cancelado','disfrutado'].includes(c.status)?`<div class="row" style="margin-top:16px">${c.status==='solicitado'?`<button onclick="changeClaim('${c.id}','aprobado')">Aprobar</button>`:''}${['aprobado','programado'].includes(c.status)?`<button class="soft" onclick="changeClaim('${c.id}','programado')">Programar</button><button class="gold" onclick="changeClaim('${c.id}','disfrutado')">Ya la disfrutamos</button>`:''}<button class="outline" onclick="changeClaim('${c.id}','cancelado')">${c.status==='solicitado'?'Rechazar':'Cancelar'} y devolver</button></div>`:''}</div>`).join('')}
function changeClaim(id,status){if(!adult)return;const c=state.claims.find(c=>c.id===id);if(!c||['cancelado','disfrutado'].includes(c.status))return;if(status==='programado'){const date=prompt('Fecha o acuerdo familiar (por ejemplo: próximo sábado):',c.date);if(!date?.trim())return;c.date=date.trim().slice(0,100)}if(status==='cancelado'){if(!confirm('¿Cancelar y devolver las monedas?'))return;if(!c.returned){state.coins+=c.cost;c.returned=true;state.ledger.push({day:day(),amount:c.cost,label:'Devolución: '+c.name,kind:'refund'})}}c.status=status;save();adultPage();$('#balance').textContent=state.coins;if(status==='disfrutado')toast('¡Qué bonito compartir un tesoro en familia!')}
function adultPage(){if(!adult){$('#app').innerHTML=`<section class="mission card"><div class="eyebrow">ESPACIO FAMILIAR · VERSIÓN DE PRUEBA</div><h1>El timón de la aventura</h1><p>Aquí puedes revisar avances y administrar experiencias.</p><div class="feedback">Todavía no hay verificación de identidad ni contraseña. Este botón solo separa las pantallas; cualquier persona con acceso a este navegador podría entrar. No es un control de seguridad.</div><button style="margin-top:25px" onclick="adult=true;adultPage()">Soy el adulto · Abrir panel de prueba</button></section>`;return}const all=state.missions;$('#app').innerHTML=`<div class="row between"><div><div class="eyebrow">PANEL DEL ADULTO</div><h1>Aprender también es acompañar</h1></div><button class="outline" onclick="adult=false;adultPage()">Cerrar panel</button></div><p class="notice">Guardado local de prueba. Las cuentas, la protección real y la sincronización se integrarán al final.</p><div class="stats"><div class="card"><strong>${all.length}</strong>misiones</div><div class="card"><strong>${state.total}</strong>monedas ganadas</div><div class="card"><strong>${all.reduce((a,m)=>a+m.first,0)}</strong>aciertos sin ayuda</div><div class="card"><strong>${all.reduce((a,m)=>a+m.help,0)}</strong>aciertos con apoyo</div></div><div class="card"><h3>Próxima práctica sugerida</h3><p>${adultRecommendation()}</p><div class="table-wrap"><table><thead><tr><th>Tema</th><th>Misiones</th><th>Sin ayuda</th><th>Con apoyo</th><th>Con error inicial</th></tr></thead><tbody>${topics.map((t,i)=>{const a=all.filter(m=>m.topic===i);return `<tr><td>${t[0]} ${t[1]}</td><td>${a.length}</td><td>${a.reduce((s,m)=>s+m.first,0)}</td><td>${a.reduce((s,m)=>s+m.help,0)}</td><td>${a.reduce((s,m)=>s+m.wrong,0)}</td></tr>`}).join('')}</tbody></table></div><h3 style="margin-top:25px">Tablas exploradas</h3><div class="row">${Array.from({length:9},(_,i)=>`<span class="pill">Tabla ${i+2}: ${all.filter(m=>m.topic===0&&m.table===i+2).length} misiones</span>`).join('')}</div><p class="small muted">Tablas mezcladas: ${all.filter(m=>m.topic===0&&m.table===0).length} misiones. Las monedas y misiones no equivalen a dominio de una tabla.</p><h3>Lecturas y observaciones</h3>${all.filter(m=>m.topic===3).map(m=>`<p class="small">${esc(m.title)} · ${m.day} · ${m.first} sin ayuda / ${m.help} con apoyo · ${esc(state.readRatings[m.id]||'Sin valoración del adulto')}</p>`).join('')||'<p class="muted small">Aún no hay lecturas completadas.</p>'}<h3>Dificultades recientes</h3>${all.filter(m=>m.errors?.length).slice(-5).map(m=>`<p class="small">${m.day} · ${esc(m.errors.join(' / '))}</p>`).join('')||'<p class="small muted">Sin errores registrados todavía.</p>'}</div><div class="split" style="margin-top:20px"><div class="card"><h3>Reglas de monedas</h3>${Object.entries({cap:'Máximo diario',mission:'Completar misión o lectura',first:'Acierto sin ayuda',help:'Corregir con apoyo',review:'Repaso diario',weekly:'Tres días por semana'}).map(([k,v])=>`<label class="setting">${v}<input id="s-${k}" type="number" min="${k==='cap'?1:0}" max="1000" value="${state.settings[k]}"></label>`).join('')}<button onclick="saveSettings()">Guardar reglas</button><p class="small muted">Los límites se calculan con la fecha de Ciudad de México. No se premia entrar ni permanecer conectado.</p></div><div class="card"><h3>Configurar experiencias</h3><p class="small muted">Estimaciones con ${estimatedSession()} monedas por sesión matemática; no incluyen bonos ni garantizan resultados.</p>${state.rewards.map(r=>`<div style="border-bottom:1px solid #dedfcf;padding:10px 0"><label class="inlinecheck"><input type="checkbox" id="enabled-${r.id}" ${r.enabled?'checked':''}> Habilitar ${r.icon}</label><input aria-label="Nombre del premio" id="name-${r.id}" value="${esc(r.name)}" style="width:100%"><label class="setting">Costo<input type="number" min="1" max="100000" id="cost-${r.id}" value="${r.cost}"></label><input id="condition-${r.id}" aria-label="Condiciones del premio" placeholder="Condiciones familiares" style="width:100%" value="${esc(r.condition)}"><p class="small muted">Aprox. ${Math.ceil(r.cost/estimatedSession())} sesiones · ${Math.ceil(r.cost/state.settings.cap)} días como mínimo, desde cero.</p></div>`).join('')}<button style="margin-top:15px" onclick="saveRewards()">Guardar experiencias</button><button class="outline" style="margin-top:10px" onclick="addReward()">+ Agregar experiencia</button></div></div><h2>Solicitudes y actividades</h2>${claimsHtml(true)}<h2>Bitácora de monedas</h2><div class="card table-wrap"><table><thead><tr><th>Fecha</th><th>Movimiento</th><th>Monedas</th></tr></thead><tbody>${state.ledger.slice().reverse().slice(0,50).map(l=>`<tr><td>${l.day}</td><td>${esc(l.label)}</td><td>${l.amount>0?'+':''}${l.amount}</td></tr>`).join('')||'<tr><td colspan="3">Todavía no hay movimientos.</td></tr>'}</tbody></table></div><button class="danger delete" onclick="resetProgress()">Borrar los datos locales de prueba</button>`}
function estimatedSession(){return Math.max(1,Math.min(state.settings.cap,state.settings.mission+5*state.settings.first))}
function adultRecommendation(){const errors=state.missions.filter(m=>m.wrong>0);if(errors.length){const m=errors[errors.length-1];return 'Conviene repasar '+topics[m.topic][1]+(m.table?' (tabla del '+m.table+')':'')+'. En la última misión de ese tema hubo '+m.wrong+' respuestas con error inicial; use las pistas y observe el procedimiento.'}return state.missions.length?'Alternar con '+topics[recommendedTopic()][1]+' para equilibrar la práctica.':'Comenzar con la tabla del 2 y una lectura corta con acompañamiento.'}
function saveSettings(){if(!adult)return;const next={};for(const k in state.settings){const n=Number($('#s-'+k).value);if(!Number.isInteger(n)||n<(k==='cap'?1:0)||n>1000)return toast('Usa cantidades enteras válidas, hasta 1000.');next[k]=n}state.settings=next;save();adultPage();toast('Reglas guardadas.')}
function saveRewards(){if(!adult)return;const next=state.rewards.map(r=>({...r,name:$('#name-'+r.id).value.trim().slice(0,80),cost:Number($('#cost-'+r.id).value),enabled:$('#enabled-'+r.id).checked,condition:$('#condition-'+r.id).value.trim().slice(0,150)}));if(next.some(r=>!r.name||!Number.isInteger(r.cost)||r.cost<1||r.cost>100000))return toast('Cada premio necesita nombre y un costo entero de 1 a 100000.');state.rewards=next;save();adultPage();toast('Experiencias actualizadas.')}
function addReward(){if(!adult)return;const name=prompt('Nombre de la nueva experiencia:');if(!name?.trim())return;state.rewards.push({id:Math.max(...state.rewards.map(r=>r.id))+1,name:name.trim().slice(0,80),icon:'🎁',cost:100,enabled:false,condition:''});save();adultPage()}
function resetProgress(){if(!adult)return;if(!confirm('Esto elimina apodo, avances, monedas y premios de este navegador. ¿Continuar?'))return;if(prompt('Escribe BORRAR para confirmar:')!=='BORRAR')return;state=defaults();adult=false;save();page('map');editProfile()}
window.addEventListener('storage',e=>{if(e.key===KEY){try{state=JSON.parse(e.newValue)||defaults();mission=null;reading=null;page('map');toast('Se actualizó el progreso desde otra pestaña.')}catch{}}});
// Original instrumental sea-adventure melody, generated locally with Web Audio.
