let audioPrefs={volume:.2,auto:true,music:true,rate:.95,voice:''};
try{Object.assign(audioPrefs,JSON.parse(localStorage.getItem('tesoro-audio-v1')||'{}'))}catch{}
if(audioPrefs.voiceVersion!==2){audioPrefs.rate=.95;audioPrefs.voice='';audioPrefs.voiceVersion=2;}
if(audioPrefs.welcomeVersion!==5){audioPrefs.auto=true;audioPrefs.music=true;audioPrefs.welcomeVersion=5;}
let sessionStarted=false;
let pendingWelcome=null;
let musicCtx=null,musicGain=null,musicOn=false,musicTimer=null,musicStep=0,musicNext=0,voiceSpeaking=false,speechGeneration=0;
const pirateScore={stepSeconds:.185,melody:[
74,0,81,77,79,76, 77,0,74,72,74,77, 79,0,82,81,79,77, 76,0,73,76,81,0,
77,0,81,84,81,79, 79,0,76,74,76,79, 82,0,79,77,74,77, 81,0,76,73,69,0,
86,0,81,84,82,79, 81,0,77,79,81,77, 79,0,74,77,76,74, 73,0,76,81,79,76,
77,0,81,79,77,74, 76,0,79,84,82,79, 77,0,74,72,70,73, 74,0,81,77,74,0],
chords:[[50,53,57],[46,50,53],[43,46,50],[45,49,52],[53,57,60],[48,52,55],[43,46,50],[45,49,52],[46,50,53],[53,57,60],[43,46,50],[45,49,52],[50,53,57],[48,52,55],[46,50,53],[45,49,52]]};
let pirateNoise=null;

function saveAudioPrefs(){try{localStorage.setItem('tesoro-audio-v1',JSON.stringify(audioPrefs))}catch{}}
function initAudio(){$('#music-volume').value=Math.round(audioPrefs.volume*100);$('#auto-voice').checked=audioPrefs.auto;$('#voice-rate').value=String(audioPrefs.rate);populateVoices();if(window.speechSynthesis)speechSynthesis.addEventListener('voiceschanged',()=>{populateVoices();if(pendingWelcome?.phase==='waiting')runWelcomeAttempt(pendingWelcome)});document.addEventListener('visibilitychange',()=>{if(document.hidden){stopNarration();if(musicOn)toggleMusic(false)}})}
function latinVoices(){if(!window.speechSynthesis)return [];return speechSynthesis.getVoices().filter(v=>/^es[-_](MX|US|AR|BO|CL|CO|CR|CU|DO|EC|GT|HN|NI|PA|PE|PR|PY|SV|UY|VE|419)$/i.test(v.lang)).sort((a,b)=>voiceScore(b)-voiceScore(a))}
function voiceScore(v){return (/neural|natural|online.*microsoft|premium|enhanced/i.test(v.name)?100:0)+(/google/i.test(v.name)?60:0)+(/^es[-_]MX$/i.test(v.lang)?20:0)+(!v.localService?10:0)}
function spanishVoices(){if(!window.speechSynthesis)return [];const latin=latinVoices();return [...latin,...speechSynthesis.getVoices().filter(v=>/^es(?:[-_]|$)/i.test(v.lang)&&!latin.some(l=>l.voiceURI===v.voiceURI)).sort((a,b)=>voiceScore(b)-voiceScore(a))]}
function preferredVoice(){const voices=spanishVoices();return voices.find(v=>v.voiceURI===audioPrefs.voice)||voices[0]||null}
function populateVoices(){const choice=$('#voice-choice');if(!window.speechSynthesis){choice.disabled=true;$('#auto-voice').disabled=true;$('#voice-status').textContent='Este navegador no admite voz. Prueba otro navegador.';return}const voices=spanishVoices(),latin=latinVoices();choice.innerHTML='<option value="">'+(latin.length?'Automática · prioridad Latinoamérica':voices.length?'Automática · español provisional':'Automática · esperando voces del dispositivo')+'</option>'+voices.map(v=>`<option value="${esc(v.voiceURI)}">${esc(v.name)} (${esc(v.lang)})</option>`).join('');choice.value=voices.some(v=>v.voiceURI===audioPrefs.voice)?audioPrefs.voice:'';const info=$('#voice-diagnostics');if(info)info.textContent='Voz v8 · '+voices.length+' voces en español detectadas';}
function unusedWaitForVoices(){if(speechSynthesis.getVoices().length)return Promise.resolve();return new Promise(resolve=>{let timer;const done=()=>{clearTimeout(timer);speechSynthesis.removeEventListener('voiceschanged',done);resolve()};speechSynthesis.addEventListener('voiceschanged',done,{once:true});timer=setTimeout(done,1200)})}
let currentUtterance=null,voiceWatchdog=null;

function updateMusicGain(){if(musicGain&&musicCtx)musicGain.gain.setTargetAtTime(musicOn?audioPrefs.volume*(voiceSpeaking?.15:1):0,musicCtx.currentTime,.12)}
function setMusicVolume(value){audioPrefs.volume=Math.max(0,Math.min(1,Number(value)/100));saveAudioPrefs();updateMusicGain()}
function instrumentNote(midi,time,duration,volume,voice='strings'){if(!midi)return;const envelope=musicCtx.createGain(),filter=musicCtx.createBiquadFilter();filter.type='lowpass';filter.frequency.value=voice==='horn'?1500:voice==='bass'?600:2700;filter.Q.value=.45;envelope.gain.setValueAtTime(0,time);envelope.gain.linearRampToValueAtTime(volume,time+(voice==='pad'?.15:.025));envelope.gain.setTargetAtTime(.001,time+Math.max(.04,duration-.15),.075);filter.connect(envelope);envelope.connect(musicGain);const count=voice==='bass'?1:2;let ended=0;for(let i=0;i<count;i++){const osc=musicCtx.createOscillator();osc.type=voice==='bass'?'triangle':voice==='horn'?(i?'triangle':'sawtooth'):'sawtooth';osc.frequency.value=440*Math.pow(2,(midi-69)/12);osc.detune.value=count===2?(i?6:-6):0;osc.connect(filter);osc.start(time);osc.stop(time+duration+.3);osc.onended=()=>{osc.disconnect();if(++ended===count){filter.disconnect();envelope.disconnect()}}}}
function pirateDrum(kind,time){const gain=musicCtx.createGain();gain.connect(musicGain);if(kind==='kick'||kind==='tom'){const osc=musicCtx.createOscillator();osc.frequency.setValueAtTime(kind==='kick'?125:185,time);osc.frequency.exponentialRampToValueAtTime(kind==='kick'?42:65,time+.18);gain.gain.setValueAtTime(kind==='kick'?.36:.18,time);gain.gain.exponentialRampToValueAtTime(.001,time+.28);osc.connect(gain);osc.start(time);osc.stop(time+.3);osc.onended=()=>{osc.disconnect();gain.disconnect()};return}if(!pirateNoise){pirateNoise=musicCtx.createBuffer(1,musicCtx.sampleRate,musicCtx.sampleRate);const data=pirateNoise.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=Math.random()*2-1}const noise=musicCtx.createBufferSource(),filter=musicCtx.createBiquadFilter();noise.buffer=pirateNoise;filter.type=kind==='cymbal'?'highpass':'bandpass';filter.frequency.value=kind==='cymbal'?6500:2200;const duration=kind==='cymbal'?.65:.15;gain.gain.setValueAtTime(kind==='cymbal'?.045:.095,time);gain.gain.exponentialRampToValueAtTime(.001,time+duration);noise.connect(filter);filter.connect(gain);noise.start(time);noise.stop(time+duration+.02);noise.onended=()=>{noise.disconnect();filter.disconnect();gain.disconnect()}}
function scheduleMusic(){if(!musicOn)return;const beat=pirateScore.stepSeconds;while(musicNext<musicCtx.currentTime+.18){const step=musicStep%192,bar=Math.floor(step/6),pulse=step%6,chord=pirateScore.chords[bar%16],theme=pirateScore.melody[step%pirateScore.melody.length],secondHalf=step>=96;if(pulse===0){chord.forEach(n=>instrumentNote(n+12,musicNext,beat*6,.018,'pad'));pirateDrum('kick',musicNext);if(bar%8===0)pirateDrum('cymbal',musicNext)}if(pulse===3){pirateDrum('snare',musicNext);instrumentNote(chord[0]-12,musicNext,beat*2,.16,'bass')}if(pulse===0)instrumentNote(chord[0]-12,musicNext,beat*2,.18,'bass');instrumentNote(chord[pulse%3],musicNext,beat*.85,.045,'strings');if(theme){instrumentNote(theme,musicNext,beat*(pulse===0?1.65:.9),.065,secondHalf?'strings':'horn');if(secondHalf&&pulse%3===0)instrumentNote(theme-12,musicNext,beat*1.4,.032,'horn')}if(pulse===5&&bar%2===1)pirateDrum('tom',musicNext);musicNext+=beat;musicStep++}}

async function toggleMusic(persist=true){try{if(!musicCtx){const AC=window.AudioContext||window.webkitAudioContext;if(!AC)return toast('La música no está disponible en este navegador.');musicCtx=new AC();musicGain=musicCtx.createGain();musicGain.gain.value=0;const limiter=musicCtx.createDynamicsCompressor();limiter.threshold.value=-14;limiter.knee.value=15;limiter.ratio.value=5;musicGain.connect(limiter);limiter.connect(musicCtx.destination)}if(!musicOn){await musicCtx.resume();musicOn=true;musicNext=musicCtx.currentTime+.05;musicStep=0;musicTimer=setInterval(scheduleMusic,80);scheduleMusic()}else{musicOn=false;clearInterval(musicTimer)}if(persist){audioPrefs.music=musicOn;saveAudioPrefs()}updateMusicGain();$('#music-toggle').textContent=musicOn?'♫ Apagar música pirata':'♫ Activar música pirata';$('#music-toggle').setAttribute('aria-pressed',String(musicOn))}catch{musicOn=false;clearInterval(musicTimer);toast('No se pudo activar la música. Intenta de nuevo o usa otro navegador.')}}
function stopNarration(keepWelcome=false){if(!keepWelcome&&pendingWelcome){clearTimeout(pendingWelcome.timer);pendingWelcome=null}speechGeneration++;clearTimeout(voiceWatchdog);if(window.speechSynthesis)speechSynthesis.cancel();voiceSpeaking=false;const status=$('#voice-status');if(status)status.textContent='';updateMusicGain()}
function pauseNarration(){if(window.speechSynthesis){speechSynthesis.pause();voiceSpeaking=false;updateMusicGain();$('#voice-status').textContent='Voz en pausa'}}
function resumeNarration(){if(window.speechSynthesis&&speechSynthesis.paused){speechSynthesis.resume();voiceSpeaking=true;updateMusicGain();$('#voice-status').textContent='Tu compañero está hablando…'}}
function setAutoVoice(on){audioPrefs.auto=on;saveAudioPrefs();if(on)narrate(`¡Hola, ${state.name||'capitana'}! Soy tu compañero de aventuras. Te ayudaré con las explicaciones y las pistas. Puedes apagar mi voz cuando quieras.`);else stopNarration()}
function spokenText(text){return text.replace(/🪙/gu,' ').replace(/×/g,' por ').replace(/÷/g,' dividido entre ').replace(/−/g,' menos ').replace(/\+/g,' más ').replace(/=/g,' igual a ').replace(/[\p{Extended_Pictographic}\uFE0F]/gu,' ').replace(/\s+/g,' ').trim()}
function narrate(text,compatible=false,startup=null){if(!window.speechSynthesis||!window.SpeechSynthesisUtterance)return toast('La voz no está disponible en este navegador. Prueba Chrome o Edge con una voz en español instalada.');stopNarration(Boolean(startup));const generation=speechGeneration;const clean=spokenText(text);if(!clean)return;$('#voice-status').textContent='Iniciando voz…';populateVoices();const u=new SpeechSynthesisUtterance(clean),chosen=compatible?(spanishVoices().find(v=>v.localService)||preferredVoice()):preferredVoice();currentUtterance=u;u.lang=chosen?.lang||'es-MX';u.rate=audioPrefs.rate;u.volume=1;u.voice=chosen||null;let started=false;
const provisional=!chosen||!latinVoices().some(v=>v.voiceURI===chosen.voiceURI);
u.onstart=()=>{if(generation!==speechGeneration)return;started=true;clearTimeout(voiceWatchdog);if(startup)startup.onStart();voiceSpeaking=true;updateMusicGain();$('#voice-status').textContent=provisional?'Hablando · voz provisional del dispositivo':'Tu compañero está hablando…'};
u.onend=()=>{if(generation!==speechGeneration)return;clearTimeout(voiceWatchdog);if(startup&&!started&&startup.onFailure('ended-before-start'))return;voiceSpeaking=false;updateMusicGain();$('#voice-status').textContent=provisional?'Se usó una voz provisional; no hay voz latinoamericana disponible.':'';currentUtterance=null};
u.onerror=e=>{if(generation!==speechGeneration)return;clearTimeout(voiceWatchdog);voiceSpeaking=false;updateMusicGain();currentUtterance=null;if(startup&&!started&&startup.onFailure(e.error))return;if(['canceled','interrupted'].includes(e.error))return;
if(!startup&&!compatible&&chosen&&!chosen.localService&&spanishVoices().some(v=>v.localService)){narrate(text,true);return}
const errors={'not-allowed':'Chrome bloqueó el inicio de voz. Pulsa directamente Probar voz y comprueba que esta pestaña no esté silenciada.','language-unavailable':'No está disponible una voz en español en Chrome.','voice-unavailable':'La voz seleccionada no está disponible. Prueba Voz compatible.','synthesis-unavailable':'El motor de voz del equipo no está disponible.','synthesis-failed':'El motor del equipo no pudo generar la voz. Prueba Voz compatible.','audio-busy':'Otra aplicación está usando el audio.','audio-hardware':'El dispositivo de audio no está disponible.','network':'La voz en línea no pudo conectarse. Prueba Voz compatible.'};
const message=(errors[e.error]||'No se pudo reproducir la voz.')+' Código: '+(e.error||'sin código')+'.';$('#voice-status').textContent=message;toast(message)};
voiceWatchdog=setTimeout(()=>{if(generation!==speechGeneration||started)return;if(startup&&startup.onFailure('timeout'))return;$('#voice-status').textContent='Chrome no inició la voz. Se detectan '+spanishVoices().length+' voces en español. Pulsa Voz compatible. Si no se escucha, indica este mensaje al adulto.';},startup?3000:6000);
try{if(speechSynthesis.paused)speechSynthesis.resume();speechSynthesis.speak(u)}catch{clearTimeout(voiceWatchdog);if(startup&&startup.onFailure('synthesis-failed'))return;$('#voice-status').textContent='No se pudo iniciar la voz. Prueba otro navegador.';currentUtterance=null}}

function startWelcome(text){stopNarration();const task={text,attempts:0,phase:'waiting',timer:null};pendingWelcome=task;runWelcomeAttempt(task)}
function runWelcomeAttempt(task){if(pendingWelcome!==task||!audioPrefs.auto||task.phase==='speaking')return;clearTimeout(task.timer);task.attempts++;task.phase='speaking';narrate(task.text,task.attempts>1,{onStart(){if(pendingWelcome!==task)return;clearTimeout(task.timer);task.phase='done';pendingWelcome=null},onFailure(error){if(pendingWelcome!==task)return false;if(task.attempts>=3||error==='not-allowed'){task.phase='done';pendingWelcome=null;return false}task.phase='waiting';$('#voice-status').textContent='Preparando la bienvenida… La voz se iniciará automáticamente.';task.timer=setTimeout(()=>runWelcomeAttempt(task),task.attempts===1?450:1000);return true}})}

function narrateLesson(){if(mission?.topic===0&&mission.stage>=1){const q=mission.stage===1?mission.guideQ:mission.questions[mission.index];narrate(`¿Cuánto es ${q.a} por ${q.b}? ${mission.stage===1?'Escribe el resultado y pulsa Comprobar.':'Elige una de las tres respuestas.'}`);return}const root=$('#lesson-content');if(!root)return toast('Abre una misión para escuchar su explicación.');if(mission?.stage===2&&!mission.answered)mission.hinted=true;const text=Array.from(root.querySelectorAll('h1,h2,h3,p,.question,.feedback')).filter(el=>!el.closest('[hidden],.objects,[aria-hidden="true"]')&&el.innerText.trim()).map(el=>el.innerText).join('. ');narrate(text||'Lee el ejercicio con calma. Puedes pedir una pista si la necesitas.')}

function showWelcome(){const returning=Boolean(state.name);const dialog=$('#launch-adventure');dialog.innerHTML=`<form id="welcome-form"><div class="eyebrow">LA TRIPULACIÓN TE ESTÁ ESPERANDO</div><div style="font-size:54px;margin-top:18px">🏴‍☠️ ${state.avatar}</div><h2>${returning?'¡Bienvenida de nuevo, '+esc(state.name)+'!':'¡Bienvenida a La aventura del tesoro!'}</h2><p>${returning?'¡Gracias por conectarte de nuevo! Tu tripulación está lista para seguir aprendiendo contigo.':'¡Gracias por conectarte! Tu primera aventura está por comenzar.'}</p><div class="feedback" style="text-align:center"><span>Tu puntaje actual</span><strong style="display:block;font-size:34px;font-family:Fredoka,sans-serif;margin:8px 0">${state.coins} 🪙</strong><span>monedas del tesoro disponibles</span></div>${!returning?`<label for="welcome-name">¿Cómo quieres que te llamemos?</label><input id="welcome-name" type="text" maxlength="24" required autocomplete="nickname" placeholder="Escribe tu nombre o apodo"><label for="welcome-avatar">Tu compañero de aventuras</label><select id="welcome-avatar"><option value="🦜">🦜 Coco, el loro pirata</option><option value="🐈">🐈 Lila, la gata pirata</option><option value="🐢">🐢 Tomás, la tortuga navegante</option><option value="🐒">🐒 Mara, la monita exploradora</option><option value="🐬">🐬 Delfi, el delfín</option></select>`:''}<p>Al comenzar se activarán la música y el saludo de tu compañero. Después puedes ajustar el sonido cuando quieras.</p><button class="gold" style="width:100%" type="submit">Comenzar</button></form>`;$('#welcome-form').onsubmit=e=>{e.preventDefault();if(!returning){const name=$('#welcome-name').value.trim();if(!name){$('#welcome-name').setCustomValidity('Escribe tu nombre o apodo.');$('#welcome-name').oninput=()=>$('#welcome-name').setCustomValidity('');$('#welcome-name').reportValidity();return}state.name=name;state.avatar=$('#welcome-avatar').value;save();page('map')}startAdventure(returning)};dialog.showModal();}
function startAdventure(returning=true){if(sessionStarted)return;sessionStarted=true;const launch=$('#launch-adventure');if(launch?.open)launch.close();audioPrefs.auto=true;audioPrefs.music=true;saveAudioPrefs();$('#auto-voice').checked=true;if(!musicOn)toggleMusic(false);const companion={'🦜':'Coco, el loro pirata','🐈':'Lila, la gata pirata','🐢':'Tomás, la tortuga navegante','🐒':'Mara, la monita exploradora','🐬':'Delfi, el delfín'}[state.avatar]||'tu compañero de aventuras';startWelcome(`¡Gracias por conectarte${returning?' de nuevo':''}, ${state.name||'capitana'}! Tu puntaje actual es de ${state.coins} ${state.coins===1?'moneda':'monedas'} del tesoro disponibles. ¡Bienvenida a bordo! Soy ${companion}. Hoy podremos explorar islas, practicar matemáticas y descubrir historias. Cada intento cuenta. ¡Pulsa una isla y comencemos la aventura!`)}
initAudio();saveAudioPrefs();page('map');showWelcome();
